const KEY='tge-circle-w02-v1::';
function grow(el){el.style.height='auto';el.style.height=(el.scrollHeight)+'px';}
let t;
function flash(){const s=document.getElementById('saved');s.classList.add('show');clearTimeout(t);t=setTimeout(()=>s.classList.remove('show'),1100);}
